SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0680000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 68, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "68", "printedPageNumber": 68, "pdfPageNumber": 451, "sequenceIndex": 58, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0680100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—II", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0680200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—III", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0680300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "Quotation—IV", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0680000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "anho) says, \"When the Prophet (Sallallaho alaihe wasallam) deputed me to Yemen, I requested him to give me some parting advice. He replied, ''Be sincere in all your services, as sincerity will magnify the value of an action, however insignificant it may be.''\"\n\nHadhrat Thaubaan (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Blessed be the sincere ones, for they are the lamps of guidance. They cause the worst evils to be driven off through their sincerity.\" It is said in another hadith, \"It is through the presence of the weak and due to their salaat and their sincerity that Allah''s help comes to all the people.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680200-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680300-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَوَيْلٌ لِلْمُصَلِّينَ ۝ الَّذِينَ هُمْ عَنْ صَلَاتِهِمْ سَاهُونَ ۝ الَّذِينَ هُمْ يُرَاءُونَ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680400-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Woe unto worshippers who are heedless of their salaat, who want but to be seen at salaat.\" (CVII: 4–6)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680500-0000-4000-8000-000000000001", "structuralNodeId": "b0680100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "\"To be heedless\" has been given the following different interpretations:\n\n1. To be so careless as to miss the correct time of salaat.\n2. To be inattentive in salaat.\n3. To forget the number of rakaats.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680600-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—III", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680700-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَىٰ يُرَاءُونَ النَّاسَ وَلَا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680800-0000-4000-8000-000000000001", "structuralNodeId": "b0680200-0000-4000-8000-000000000001", "sequenceIndex": 8, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"When they (the hypocrites) stand up for salaat, they perform it without earnestness and want but to be seen by men and are mindful of Allah but little.\" (IV: 142)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0680900-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 9, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Quotation—IV", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681000-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 10, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ أَضَاعُوا الصَّلَاةَ وَاتَّبَعُوا الشَّهَوَاتِ فَسَوْفَ يَلْقَوْنَ غَيًّا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}, {"id": "f0681100-0000-4000-8000-000000000001", "structuralNodeId": "b0680300-0000-4000-8000-000000000001", "sequenceIndex": 11, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Now there hath succeeded them (Prophets) a later generation who have ruined salaat and have followed lusts. So they will meet Ghayy.\" (XIX: 59)", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 68"}]}'::jsonb);